forcedColors:
@media (forced-colors: active) {
  :root {
    --jt-canvas: Canvas;
    --jt-surface: Canvas;
    --jt-surface-soft: Canvas;
    --jt-text: CanvasText;
    --jt-text-muted: GrayText;
    --jt-text-subtle: GrayText;
    --jt-accent: Highlight;
    --jt-accent-hover: Highlight;
    --jt-accent-ui: Highlight;
    --jt-on-accent: CanvasText;
    --jt-border: GrayText;
  }
}

full:
:root {
  --jt-canvas: #fafaf7;
  --jt-surface: #f9f9f6;
  --jt-surface-soft: #fafaf7;
  --jt-text: #0a191a;
  --jt-text-muted: #3b4b4d;
  --jt-text-subtle: #576769;
  --jt-accent: #17575d;
  --jt-accent-hover: #0c4045;
  --jt-accent-ui: #08717a;
  --jt-on-accent: #fafaf7;
  --jt-border: #5a6668;
}

@supports (color: color(display-p3 0 0 0)) {
  :root {
    --jt-accent: color(display-p3 0.0900 0.3448 0.3802);
    --jt-accent-hover: color(display-p3 0.0000 0.2580 0.2931);
  }
}

